<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Customer,Product,License,Installation,Release,SecurityEvent};
class DashboardController extends Controller { public function __invoke(){return view('dashboard',['metrics'=>['customers'=>Customer::count(),'products'=>Product::count(),'licenses'=>License::count(),'active_licenses'=>License::where('status','active')->count(),'suspended_licenses'=>License::where('status','suspended')->count(),'expired_licenses'=>License::where(fn($q)=>$q->where('status','expired')->orWhere('expires_at','<',now()))->count(),'revoked_licenses'=>License::where('status','revoked')->count(),'installations'=>Installation::count(),'active_installations'=>Installation::where('status','active')->count(),'locked_installations'=>Installation::where('status','locked')->count(),'offline_installations'=>Installation::where('last_seen_at','<',now()->subSeconds(config('office.offline_after_seconds')))->count(),'clone_events'=>SecurityEvent::where('type','clone_detected')->count()],'recent'=>Installation::latest('last_seen_at')->limit(8)->get(),'releases'=>Release::with('product')->where('status','published')->latest('published_at')->limit(6)->get(),'security'=>SecurityEvent::latest('occurred_at')->limit(6)->get()]);} }
